<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Maze Bots</title>
<style>
body{margin:0;font-family:sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center}
#maze{border:2px solid #444;margin-top:10px}
#info{margin:10px;display:flex;gap:20px;align-items:center}
button{padding:6px 12px}
</style>
</head>
<body>
<div id="maze"><canvas id="canvas" width="800" height="800"></canvas></div>
<div id="info">
<span>Completed: <span id="completed">0</span>/24</span>
<span>Timer: <span id="timer">0</span></span>
<button id="reset">Reset</button>
</div>
<script>
(() => {
  const rows = 31, cols = 31;
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const completedEl = document.getElementById('completed');
  const timerEl = document.getElementById('timer');
  document.getElementById('reset').onclick = () => game.reset();

  function mulberry32(a){return function(){let t=a+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
  function shuffle(arr,rng){for(let i=arr.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}}

  let walls, spawn, exit, bots, elapsed = 0;

  function generateMaze(rng){
    const w = Array.from({length:rows},()=>Array.from({length:cols},()=>({n:true,e:true,s:true,w:true})));
    const vis = Array.from({length:rows},()=>Array(cols).fill(false));
    const stack = [{r:0,c:0}];
    vis[0][0]=true;
    while(stack.length){
      const cur = stack[stack.length-1];
      const dirs = [
        {dr:-1,dc:0,wall:'n',opp:'s'},
        {dr:0,dc:1,wall:'e',opp:'w'},
        {dr:1,dc:0,wall:'s',opp:'n'},
        {dr:0,dc:-1,wall:'w',opp:'e'}
      ];
      const neigh=[];
      for(const d of dirs){
        const nr=cur.r+d.dr,nc=cur.c+d.dc;
        if(nr>=0&&nr<rows&&nc>=0&&nc<cols&&!vis[nr][nc]) neigh.push({nr,nc,d});
      }
      if(neigh.length){
        const choice = neigh[Math.floor(rng()*neigh.length)];
        w[cur.r][cur.c][choice.d.wall]=false;
        w[choice.nr][choice.nc][choice.d.opp]=false;
        vis[choice.nr][choice.nc]=true;
        stack.push({r:choice.nr,c:choice.nc});
      }else stack.pop();
    }
    return w;
  }

  function initBots(rng){
    const bots=[];
    for(let i=0;i<24;i++){
      const dirs=['n','e','s','w'];
      shuffle(dirs,rng);
      const b={
        index:i,
        r:spawn.r,c:spawn.c,
        path:[{r:spawn.r,c:spawn.c}],
        deadEnds:[],
        finishTick:null,
        stack:[{r:spawn.r,c:spawn.c}],
        visited:new Set([`${spawn.r},${spawn.c}`]),
        dirOrder:dirs
      };
      bots.push(b);
    }
    return bots;
  }

  function reset(seed){
    if(seed===undefined) seed = Date.now()|0;
    const rng = mulberry32(seed);
    walls = generateMaze(rng);
    spawn = {r:0,c:0};
    exit = {r:rows-1,c:cols-1};
    bots = initBots(rng);
    elapsed = 0;
    updateUI();
  }

  function stepBot(bot){
    if(bot.finishTick!==null) return;
    const r=bot.r,c=bot.c;
    if(r===exit.r && c===exit.c){bot.finishTick=elapsed;return;}
    let moved=false;
    for(const d of bot.dirOrder){
      let dr=0,dc=0;
      if(d==='n') dr=-1; else if(d==='e') dc=1; else if(d==='s') dr=1; else if(d==='w') dc=-1;
      const nr=r+dr,nc=c+dc;
      if(nr<0||nr>=rows||nc<0||nc>=cols) continue;
      let open=false;
      if(d==='n' && !walls[r][c].n) open=true;
      if(d==='e' && !walls[r][c].e) open=true;
      if(d==='s' && !walls[r][c].s) open=true;
      if(d==='w' && !walls[r][c].w) open=true;
      if(!open) continue;
      const key=`${nr},${nc}`;
      if(!bot.visited.has(key)){
        bot.r=nr; bot.c=nc;
        bot.stack.push({r:nr,c:nc});
        bot.visited.add(key);
        bot.path.push({r:nr,c:nc});
        moved=true;
        if(nr===exit.r && nc===exit.c) bot.finishTick=elapsed;
        break;
      }
    }
    if(!moved){
      if(!bot.deadEnds.some(cell=>cell.r===r&&cell.c===c)) bot.deadEnds.push({r,c});
      if(bot.stack.length>1){
        bot.stack.pop();
        const prev=bot.stack[bot.stack.length-1];
        bot.r=prev.r; bot.c=prev.c;
        bot.path.push({r:bot.r,c:bot.c});
        if(bot.r===exit.r && bot.c===exit.c) bot.finishTick=elapsed;
      }
    }
  }

  function tick(n){
    if(bots.every(b=>b.finishTick!==null)) return;
    for(let i=0;i<n;i++){
      if(bots.every(b=>b.finishTick!==null)) break;
      elapsed++;
      for(const b of bots) stepBot(b);
      updateUI();
    }
  }

  function updateUI(){
    completedEl.textContent = bots.filter(b=>b.finishTick!==null).length;
    timerEl.textContent = elapsed;
  }

  const cellSize = canvas.width/cols;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.strokeStyle='#555'; ctx.lineWidth=2;
    for(let r=0;r<rows;r++){
      for(let c=0;c<cols;c++){
        const x=c*cellSize, y=r*cellSize;
        const w=walls[r][c];
        if(w.n) {ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+cellSize,y);ctx.stroke();}
        if(w.w) {ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y+cellSize);ctx.stroke();}
        if(w.e) {ctx.beginPath();ctx.moveTo(x+cellSize,y);ctx.lineTo(x+cellSize,y+cellSize);ctx.stroke();}
        if(w.s) {ctx.beginPath();ctx.moveTo(x,y+cellSize);ctx.lineTo(x+cellSize,y+cellSize);ctx.stroke();}
      }
    }
    // spawn/exit
    ctx.fillStyle='#0f0';
    ctx.fillRect(spawn.c*cellSize+cellSize*0.3,spawn.r*cellSize+cellSize*0.3,cellSize*0.4,cellSize*0.4);
    ctx.fillStyle='#f00';
    ctx.fillRect(exit.c*cellSize+cellSize*0.3,exit.r*cellSize+cellSize*0.3,cellSize*0.4,cellSize*0.4);
    // bots
    for(const b of bots){
      const tx=(b.c+0.5)*cellSize;
      const ty=(b.r+0.5)*cellSize;
      if(b.renderX===undefined){b.renderX=tx;b.renderY=ty;}
      b.renderX += (tx-b.renderX)*0.2;
      b.renderY += (ty-b.renderY)*0.2;
      ctx.beginPath();
      ctx.arc(b.renderX,b.renderY,cellSize*0.22,0,Math.PI*2);
      ctx.fillStyle=`hsl(${(b.index*15)%360},80%,55%)`;
      ctx.fill();
      ctx.strokeStyle='#000'; ctx.lineWidth=1; ctx.stroke();
    }
    requestAnimationFrame(draw);
  }
  draw();

  window.game = {
    tick,
    reset,
    get elapsed(){return elapsed;},
    get size(){return {rows,cols};},
    get spawn(){return spawn;},
    get exit(){return exit;},
    walls(r,c){return walls[r][c];},
    get bots(){return bots;}
  };
  reset(12345);
})();
</script>
</body>
</html>
